{
  if (what & TEST_NFC)
    {
      size_t plen;
      uint32_t *p = u32_normalize (UNINORM_NFC, label, llen,
                                   NULL, &plen);
      int ok;
      if (p == NULL)
        {
          if (errno == ENOMEM)
            return IDN2_MALLOC;
          return IDN2_NFC;
        }
      ok = llen == plen && memcmp (label, p, plen * sizeof (*label)) == 0;
