            }

            return IDN2_DISALLOWED;
          }
    }

  if (what & TEST_CONTEXTJ)
    {
      size_t i;
      for (i = 0; i < llen; i++)
        if (_idn2_contextj_p (label[i]))
          return IDN2_CONTEXTJ;
    }

  if (what & TEST_CONTEXTJ_RULE)
    {
      size_t i;
      int rc;

      for (i = 0; i < llen; i++)
        {
          rc = _idn2_contextj_rule (label, llen, i);
          if (rc != IDN2_OK)
