      size_t i;
      for (i = 0; i < llen; i++)
        if (_idn2_unassigned_p (label[i]))
          return IDN2_UNASSIGNED;
    }

  if (what & TEST_BIDI)
    {
      int rc = _idn2_bidi (label, llen);
